  discardTitle: "\u5909\u66F4\u3092\u7834\u68C4\u3057\u307E\u3059\u304B\uFF1F",
  discardDescription: "\u3053\u3053\u3067\u306E\u5909\u66F4\u306F\u307E\u3060\u4FDD\u5B58\u3055\u308C\u3066\u3044\u307E\u305B\u3093\u3002",
