  fileFolder: (name) => `${name}\u306F\u30D5\u30A9\u30EB\u30C0\u30FC\u3067\u3059: \u4E2D\u306E\u30D5\u30A1\u30A4\u30EB\u3092\u9078\u629E\u3057\u3066\u304F\u3060\u3055\u3044\u3002`,
  fileAlreadyAdded: (name) => `${name}\u306F\u3059\u3067\u306B\u8FFD\u52A0\u3055\u308C\u3066\u3044\u307E\u3059\u3002`,
